// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzzed params: an address 'from', an array of one recipient, and a value array
    function testFuzz_property(address from, address dummy, uint256 v0) public {
        // Keep domain sensible: single-recipient case (we record exactly one call)
        address[] memory tos = new address[](1);
        uint[] memory vals = new uint[](1);

        // We must deploy a recording helper that implements the exact signature transferFrom(address,address,uint256)
        // so that low-level call from C is observable. Use the helper's address as caddress argument.
        Recorder r = new Recorder();
        tos[0] = address(0xBEEF); // this will be passed as the _tos element to c.call target
        vals[0] = v0;

        // Ensure _tos.length > 0 as required by C.transfer
        // Call c.transfer and observe whether it reverts or not. The correct contract should not revert
        // because our Recorder will accept the call and return true. The mutant that reverts before calling
        // will cause transfer to revert for these inputs (any non-empty _tos).

        bool ok;
        try c.transfer(from, address(r), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any inputs with non-empty tos (we provide length 1), transfer should succeed
        // (ok == true) on the reference implementation. The mutant that unconditionally reverts will make ok==false
        assertTrue(ok);

        // Additionally ensure the recorder observed exactly one call with expected decoded args when call succeeded
        // (this reads the helper's recorded public state — allowed per rules)
        (address recordedFrom, address recordedTo, uint256 recordedVal, uint256 calls) = r.last();
        assertTrue(calls == 1 && recordedFrom == from && recordedTo == tos[0] && recordedVal == vals[0]);
    }
}

// Recorder matches the ABI selector bytes4(keccak256("transferFrom(address,address,uint256)"))
contract Recorder {
    address public lastFrom;
    address public lastTo;
    uint256 public lastVal;
    uint256 public callCount;

    // The function signature must match so abi.decode occurs naturally
    function transferFrom(address from, address to, uint256 val) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastVal = val;
        callCount += 1;
        return true;
    }

    // helper to read all at once
    function last() external view returns (address, address, uint256, uint256) {
        return (lastFrom, lastTo, lastVal, callCount);
    }
}
